<template>
  <main class="adminPage">
    <aside class="adminSidebar"><brandLogo /><span class="endLabel">平台管理</span><el-button text @click="router.push('/home')">← 返回创作</el-button><nav aria-label="平台管理导航"><el-tooltip v-for="item in sections" :key="item.id" :content="item.label" placement="right" :showAfter="200"><button type="button" :aria-label="item.label" :aria-current="section === item.id ? 'page' : undefined" @click="section = item.id"><component :is="item.icon" :size="18" />{{ item.label }}</button></el-tooltip></nav><accountMenu @openSettings="settingsVisible = true" /></aside>
    <section class="adminContent">
      <header class="pageHeader"><div><span class="eyebrow">AFXEN / 平台管理</span><h1>{{ sections.find(item => item.id === section)?.label }}</h1></div><el-tag v-if="platform.scope === 'scenario'" type="warning">隔离预览 · 非真实业务数据</el-tag></header>
      <el-alert v-if="platformError" :title="platformError" type="error" :closable="false"><el-button text @click="loadPlatform">重试读取</el-button></el-alert>
      <p v-if="platformLoading" role="status">正在读取…</p>
      <template v-if="!platformError">
        <template v-if="section === 'customers'">
          <template v-if="!selectedCustomer"><div class="sectionToolbar"><el-input v-model="customerSearch" aria-label="搜索客户" placeholder="搜索客户名称" clearable /><el-button type="primary" @click="openCustomer()">创建客户</el-button></div><el-table :data="filteredCustomers" emptyText="暂无客户"><el-table-column prop="name" label="客户名称" /><el-table-column label="模型授权"><template #default="{ row }">{{ row.modelIds.length }} 款模型</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button text @click="selectedCustomerId = row.id; customerTab = 'accounts'">账号管理</el-button><el-button text @click="selectedCustomerId = row.id; customerTab = 'models'">模型授权</el-button><el-button text @click="openCustomer(row as Customer)">编辑</el-button></template></el-table-column></el-table></template>
          <template v-else><el-button text @click="selectedCustomerId = ''">← 返回客户列表</el-button><h2>{{ selectedCustomer.name }}</h2><el-tabs v-model="customerTab"><el-tab-pane label="账号管理" name="accounts"><customerAccounts :customerId="selectedCustomer.id" /></el-tab-pane><el-tab-pane label="模型授权" name="models"><p>同客户账号使用同一组授权模型，客户管理员不能扩大授权。</p><el-button type="primary" @click="openCustomer(selectedCustomer)">编辑授权与默认模型</el-button><div class="modelGrid"><article v-for="model in state.models.filter(item => selectedCustomer?.modelIds.includes(item.id))" :key="model.id"><strong>{{ model.name }}</strong><p>{{ model.description }}</p><el-tag :type="model.enabled ? 'success' : 'info'">{{ model.enabled ? '已上架' : '已下架' }}</el-tag></article></div></el-tab-pane></el-tabs></template>
        </template>
        <template v-if="section === 'models'">
          <el-tabs v-model="modelTab"><el-tab-pane label="服务连接" name="connections"><div class="sectionToolbar"><p>认证由平台保管；连接验证与模型生成验证分开记录</p><el-button type="primary" @click="openConnection()">新增连接</el-button></div><el-table :data="state.connections" emptyText="暂无服务连接"><el-table-column prop="name" label="连接名称" /><el-table-column prop="protocol" label="协议" /><el-table-column label="状态"><template #default="{ row }">{{ row.enabled ? '已启用' : '已停用' }}</template></el-table-column><el-table-column label="最近验证"><template #default="{ row }">{{ row.verification || '未验证' }}<small>{{ row.verifiedAt ? formatDate(row.verifiedAt) : '' }}</small></template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button text @click="openConnection(row as ServiceConnection)">编辑</el-button><el-button text :disabled="busy" @click="perform({ type: 'verifyConnection', id: row.id })">验证连接</el-button></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane label="模型目录" name="catalog"><div class="sectionToolbar"><p>上架后仍需客户授权；未验证能力不向用户开放</p><el-button type="primary" @click="openModel()">新增模型</el-button></div><div class="modelGrid"><article v-for="model in state.models" :key="model.id"><div class="modelHeading"><el-tag>{{ kindLabels[model.kind] }}</el-tag><el-tag :type="model.enabled ? 'success' : 'info'">{{ model.enabled ? '已上架' : '已下架' }}</el-tag></div><h3>{{ model.name }}</h3><code>{{ model.id }}</code><p>{{ model.description }}</p><small>连接：{{ state.connections.find(item => item.id === model.connectionId)?.name || '未配置' }} · {{ model.verified ? '模型已验证' : '模型未验证' }}</small><footer><el-button text @click="openModel(model)">能力与参数</el-button><el-button text :disabled="busy" @click="perform({ type: 'verifyModel', id: model.id })">验证模型</el-button><el-button text @click="openNotice(model.id)">参数调整通知</el-button></footer></article></div></el-tab-pane></el-tabs>
        </template>
        <template v-if="section === 'templates'"><div class="sectionToolbar"><p>仅平台管理员提交与维护；可见范围和模型使用权限分别校验</p><el-button type="primary" @click="openTemplate()">提交模板</el-button></div><el-table :data="state.templates" emptyText="暂无平台模板"><el-table-column prop="name" label="名称" /><el-table-column label="类型"><template #default="{ row }">{{ row.kind === 'project' ? '项目模板' : '视频模板' }}</template></el-table-column><el-table-column label="可见范围"><template #default="{ row }">{{ row.customerIds.length ? row.customerIds.map((id: string) => state.customers.find(item => item.id === id)?.name).join('、') : '全部客户' }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ row.enabled ? '已发布' : '未发布' }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button text @click="openTemplate(row as PlatformTemplate)">内容与范围</el-button></template></el-table-column></el-table></template>
        <template v-if="section === 'usage'"><div class="usageFilters"><el-select v-model="usageCustomer" clearable placeholder="全部客户" aria-label="统计客户"><el-option v-for="item in state.customers" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-select v-model="usageAccount" clearable placeholder="全部账号" aria-label="统计账号"><el-option v-for="item in usageAccounts" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-select v-model="usageModel" clearable placeholder="全部模型" aria-label="统计模型"><el-option v-for="item in state.models" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-date-picker v-model="usageDates" type="daterange" startPlaceholder="开始日期" endPlaceholder="结束日期" /></div><div class="usageSummary"><article v-for="status in ['all', 'completed', 'failed', 'running']" :key="status"><span>{{ status === 'all' ? '任务总数' : status === 'running' ? '处理中' : taskLabels[status as PlatformTask['status']] }}</span><strong>{{ usageTasks.filter(item => status === 'all' || (status === 'running' ? ['waiting','running','saving','unknown'].includes(item.status) : item.status === status)).length }}</strong></article></div><p>按实际单位分别记录；未返回用量不计作零。本期不收费，不展示私人提示词或生成结果。</p><el-table :data="usageTasks" emptyText="暂无用量记录"><el-table-column prop="modelId" label="模型" /><el-table-column label="状态"><template #default="{ row }">{{ taskLabels[row.status as PlatformTask['status']] }}</template></el-table-column><el-table-column prop="elapsed" label="耗时" /><el-table-column prop="usage" label="实际用量及单位" /><el-table-column label="时间"><template #default="{ row }">{{ formatDate(row.createdAt) }}</template></el-table-column></el-table></template>
        <template v-if="section === 'messages'"><div class="sectionToolbar"><p>模型参数通知仅由平台管理员发布</p><el-button type="primary" @click="openNotice()">发布通知</el-button></div><messageCenter management /></template>
      </template>
    </section>
    <el-dialog v-model="customerVisible" title="客户与模型授权" width="min(680px, 94vw)" :closeOnClickModal="false"><el-form v-if="customerDraft" labelPosition="top"><el-form-item label="客户名称"><el-input v-model="customerDraft.name" :maxlength="100" /></el-form-item><el-form-item label="可用模型"><el-checkbox-group v-model="customerDraft.modelIds" @change="syncCustomerDefaults"><el-checkbox v-for="model in state.models" :key="model.id" :value="model.id" :disabled="(!model.enabled || !model.verified) && !customerDraft.modelIds.includes(model.id)">{{ model.name }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item v-for="kind in kinds" :key="kind" :label="`${kindLabels[kind]}默认模型`"><el-select v-model="customerDraft.defaults[kind]" clearable><el-option v-for="model in state.models.filter(item => item.kind === kind && customerDraft?.modelIds.includes(item.id) && item.enabled)" :key="model.id" :value="model.id" :label="model.name" /></el-select></el-form-item><el-form-item label="并发任务上限"><el-input-number v-model="customerDraft.limit" :min="1"  /></el-form-item><p>取消授权会同时清空对应默认模型；保存后阻止新提交，历史作品保留。</p></el-form><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="customerVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveCustomer">保存</el-button></template></el-dialog>
    <el-dialog v-model="connectionVisible" title="服务连接" width="min(640px, 94vw)" :closeOnClickModal="false" @closed="credential = ''"><el-form v-if="connectionDraft" labelPosition="top"><el-form-item label="连接名称"><el-input v-model="connectionDraft.name" /></el-form-item><el-form-item label="协议"><el-select v-model="connectionDraft.protocol"><el-option v-for="item in ['OpenAI Chat Completions', 'DashScope 原生媒体', 'Seed Audio']" :key="item" :value="item" /></el-select></el-form-item><el-form-item label="HTTPS服务地址"><el-input v-model="connectionDraft.endpoint" /></el-form-item><el-form-item label="认证信息"><el-input v-model="credential" type="password" showPassword autocomplete="new-password" placeholder="已保存的认证不回显；填写以替换" /></el-form-item><el-form-item label="允许新任务"><el-switch v-model="connectionDraft.enabled" /></el-form-item><p>停用将阻止关联模型的新提交，历史作品保留。保存不触发生成，验证需明确点击。</p></el-form><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="connectionVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveConnection">保存连接</el-button></template></el-dialog>
    <el-dialog v-model="modelVisible" title="模型能力与参数" width="min(960px, 94vw)" :closeOnClickModal="false"><div v-if="modelDraft" class="modelEditor"><el-form labelPosition="top"><el-form-item label="模型名称"><el-input v-model="modelDraft.name" /></el-form-item><el-form-item label="服务侧模型标识"><el-input v-model="modelDraft.id" :disabled="editingModel" /></el-form-item><el-form-item label="模型类型"><el-select v-model="modelDraft.kind"><el-option v-for="kind in kinds" :key="kind" :value="kind" :label="kindLabels[kind]" /></el-select></el-form-item><el-form-item label="所属连接"><el-select v-model="modelDraft.connectionId"><el-option v-for="item in state.connections" :key="item.id" :value="item.id" :label="item.name" /></el-select></el-form-item><el-form-item label="能力与输入限制"><el-input v-model="modelDraft.description" type="textarea" :rows="3" /></el-form-item><el-form-item label="上架状态"><el-switch v-model="modelDraft.enabled" :disabled="!modelDraft.verified" /><span>{{ modelDraft.verified ? '已验证' : '请先保存并验证模型' }}</span></el-form-item><h3>参数定义</h3><el-button @click="addParameter">新增参数</el-button><section v-for="parameter in modelDraft.parameters" :key="parameter.key" class="parameterRow"><el-input v-model="parameter.name" aria-label="参数显示名称" placeholder="显示名称" /><el-input v-model="parameter.key" aria-label="参数标识" placeholder="参数标识" /><el-input :modelValue="parameter.options.join('、')" aria-label="可选值" @update:modelValue="parameter.options = String($event).split('、').filter(Boolean)" /><el-select v-model="parameter.value" aria-label="默认值"><el-option v-for="option in parameter.options" :key="option" :value="option" /></el-select><el-checkbox v-model="parameter.exposed">向用户开放</el-checkbox><el-checkbox v-model="parameter.required">必填</el-checkbox><el-button text type="danger" @click="modelDraft.parameters = modelDraft.parameters.filter(item => item !== parameter)">移除参数</el-button></section></el-form><aside class="userPreview"><h3>用户端预览</h3><strong>{{ modelDraft.name }}</strong><p>{{ modelDraft.description }}</p><el-form labelPosition="top"><el-form-item v-for="parameter in modelDraft.parameters.filter(item => item.exposed)" :key="parameter.key" :label="parameter.name" :required="parameter.required"><el-select :modelValue="parameterPreview[parameter.key] || parameter.value" @update:modelValue="parameterPreview[parameter.key] = String($event)"><el-option v-for="option in parameter.options" :key="option" :value="option" /></el-select></el-form-item></el-form><p>只展示实际有效能力；参数组合与素材约束由模型适配定义。</p></aside></div><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="modelVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveModel">保存模型配置</el-button></template></el-dialog>
    <el-dialog v-model="noticeVisible" title="发布模型参数调整通知" width="min(680px, 94vw)" :closeOnClickModal="false"><el-form v-if="noticeDraft" labelPosition="top"><el-form-item label="受影响模型"><el-select v-model="noticeDraft.modelId"><el-option v-for="model in state.models" :key="model.id" :value="model.id" :label="model.name" /></el-select></el-form-item><el-form-item label="通知标题"><el-input v-model="noticeDraft.title" /></el-form-item><el-form-item label="调整前后说明"><el-input v-model="noticeDraft.content" type="textarea" :rows="3" /></el-form-item><el-form-item label="生效时间"><el-date-picker v-model="noticeDraft.effectiveAt" type="datetime" valueFormat="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="草稿影响与用户需执行的操作"><el-input v-model="noticeDraft.impact" type="textarea" :rows="3" /></el-form-item><el-form-item label="接收客户（默认全部受影响客户）"><el-select v-model="noticeDraft.customerIds" multiple><el-option v-for="customer in state.customers.filter(item => item.modelIds.includes(noticeDraft!.modelId))" :key="customer.id" :value="customer.id" :label="customer.name" /></el-select></el-form-item><el-checkbox v-model="noticeConfirmed">已核对实际保存的调整或已明确安排的生效时间</el-checkbox><div class="notificationPreview"><h3>用户收到的通知预览</h3><strong>{{ noticeDraft.title }}</strong><p>{{ noticeDraft.content }}</p><p>{{ noticeDraft.impact }}</p><small>{{ noticeDraft.effectiveAt }}</small></div></el-form><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="noticeVisible = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!noticeConfirmed" @click="saveNotice">确认发布</el-button></template></el-dialog>
    <el-dialog v-model="templateVisible" title="平台模板内容与范围" width="min(640px, 94vw)" :closeOnClickModal="false"><el-form v-if="templateDraft" labelPosition="top"><el-form-item label="模板名称"><el-input v-model="templateDraft.name" /></el-form-item><el-form-item label="类型"><el-radio-group v-model="templateDraft.kind"><el-radio value="video">视频模板</el-radio><el-radio value="project">项目模板</el-radio></el-radio-group></el-form-item><el-form-item label="模板文件"><input ref="templateFileInput" type="file" :accept="templateDraft.kind === 'video' ? 'video/mp4' : 'application/json,.json'" hidden @change="pickTemplateFile" /><el-button @click="templateFileInput?.click()">选择{{ templateDraft.kind === 'video' ? '视频' : '项目快照' }}</el-button><span>{{ templateFile?.name || templateDraft.sourceName }}</span></el-form-item><el-form-item label="内容说明"><el-input v-model="templateDraft.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="依赖模型"><el-select v-model="templateDraft.modelIds" multiple><el-option v-for="model in state.models" :key="model.id" :label="model.name" :value="model.id" /></el-select></el-form-item><el-form-item label="可见客户（不选为全部客户）"><el-select v-model="templateDraft.customerIds" multiple><el-option v-for="customer in state.customers" :key="customer.id" :label="customer.name" :value="customer.id" /></el-select></el-form-item><el-form-item label="发布"><el-switch v-model="templateDraft.enabled" /></el-form-item><p>隔离预览仅保留本页内存，不代表真实上传。正式文件保存由模板接口承接。</p></el-form><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="templateVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveTemplate">保存</el-button></template></el-dialog>
    <settings v-model="settingsVisible" />
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox } from "element-plus";
import { IconUsers, IconCpu, IconLayoutGrid, IconChartBar, IconBell } from "@tabler/icons-vue";
import brandLogo from "@/components/brandLogo.vue";
import accountMenu from "@/components/accountMenu.vue";
import customerAccounts from "@/components/customerAccounts.vue";
import messageCenter from "@/components/messageCenter.vue";
import settings from "@/components/settings/index.vue";
import { platformState as state, loadPlatform, platformError, platformLoading, savePlatform } from "@/stores/platform";
import { platform, taskLabels, type Customer, type PlatformModel, type PlatformNotice, type ServiceConnection, type PlatformTemplate, type PlatformCommand, type PlatformTask } from "@/ports/platform";
const route = useRoute(), router = useRouter();
const sections = [{ id: "customers", label: "客户与账号", icon: IconUsers }, { id: "models", label: "模型管理", icon: IconCpu }, { id: "templates", label: "模板管理", icon: IconLayoutGrid }, { id: "usage", label: "使用统计", icon: IconChartBar }, { id: "messages", label: "消息管理", icon: IconBell }];
const section = computed({ get: () => sections.some(item => item.id === route.query.section) ? String(route.query.section) : "customers", set: value => { void router.replace({ path: "/admin", query: { section: value } }); } });
const settingsVisible = ref(false), selectedCustomerId = ref(""), customerTab = ref("accounts"), modelTab = ref("connections"), customerSearch = ref("");
const filteredCustomers = computed(() => state.value.customers.filter(item => item.name.includes(customerSearch.value.trim())));
const selectedCustomer = computed(() => state.value.customers.find(item => item.id === selectedCustomerId.value));
const busy = ref(false), dialogError = ref("");
const customerVisible = ref(false), customerDraft = ref<Customer>();
const connectionVisible = ref(false), connectionDraft = ref<ServiceConnection>(), credential = ref("");
const parameterPreview = ref<Record<string, string>>({});
const modelVisible = ref(false), modelDraft = ref<PlatformModel>(), editingModel = ref(false);
const noticeVisible = ref(false), noticeDraft = ref<PlatformNotice>(), noticeConfirmed = ref(false);
watch(() => noticeDraft.value?.modelId, modelId => { if (noticeDraft.value) noticeDraft.value.customerIds = state.value.customers.filter(item => item.modelIds.includes(modelId ?? "")).map(item => item.id); });
const templateVisible = ref(false), templateDraft = ref<PlatformTemplate>();
const templateFileInput = ref<HTMLInputElement>(), templateFile = ref<File>();
const kinds = ["text", "image", "video", "audio"] as const;
const kindLabels = { text: "文字／脚本", image: "图片", video: "视频", audio: "音频" };
const usageCustomer = ref(""), usageAccount = ref(""), usageModel = ref(""), usageDates = ref<[Date, Date]>();
const usageAccounts = computed(() => state.value.accounts.filter(item => !usageCustomer.value || item.customerId === usageCustomer.value));
watch(usageCustomer, () => { usageAccount.value = ""; });
const usageTasks = computed(() => state.value.tasks.filter(item => (!usageCustomer.value || item.customerId === usageCustomer.value) && (!usageAccount.value || item.accountId === usageAccount.value) && (!usageModel.value || item.modelId === usageModel.value) && (!usageDates.value || new Date(item.createdAt) >= usageDates.value[0] && new Date(item.createdAt).getTime() < usageDates.value[1].getTime() + 86400000)));
function formatDate(value: string) { return new Date(value).toLocaleString(); }
function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)); }
function openCustomer(value?: Customer) { customerDraft.value = value ? clone(value) : { id: crypto.randomUUID(), name: "", modelIds: [], defaults: {}, limit: 1 }; dialogError.value = ""; customerVisible.value = true; }
function openConnection(value?: ServiceConnection) { connectionDraft.value = value ? clone(value) : { id: crypto.randomUUID(), name: "", protocol: "OpenAI Chat Completions", endpoint: "", enabled: false }; credential.value = ""; dialogError.value = ""; connectionVisible.value = true; }
function openModel(value?: PlatformModel) { parameterPreview.value = {}; editingModel.value = !!value; modelDraft.value = value ? clone(value) : { id: "", name: "", kind: "text", connectionId: "", description: "", enabled: false, verified: false, parameters: [] }; dialogError.value = ""; modelVisible.value = true; }
function openNotice(modelId = "") { noticeDraft.value = { id: crypto.randomUUID(), title: "", modelId, content: "", impact: "", effectiveAt: "", customerIds: state.value.customers.filter(item => item.modelIds.includes(modelId)).map(item => item.id), createdAt: new Date().toISOString(), read: false }; noticeConfirmed.value = false; dialogError.value = ""; noticeVisible.value = true; }
function openTemplate(value?: PlatformTemplate) { templateFile.value = undefined; templateDraft.value = value ? clone(value) : { id: crypto.randomUUID(), name: "", kind: "video", description: "", customerIds: [], modelIds: [], enabled: false }; dialogError.value = ""; templateVisible.value = true; }
async function perform(command: PlatformCommand, close?: () => void) {
  if (busy.value) return; busy.value = true; dialogError.value = "";
  try { await savePlatform(command); close?.(); ElMessage.success(platform.scope === "scenario" ? "演示状态已更新，未写入真实服务" : "操作成功"); }
  catch (cause) { dialogError.value = cause instanceof Error ? cause.message : "保存失败"; ElMessage.error(dialogError.value); }
  finally { busy.value = false; }
}
function syncCustomerDefaults() {
  const customer = customerDraft.value;
  if (!customer) return;
  for (const [kind, modelId] of Object.entries(customer.defaults)) {
    if (modelId && !customer.modelIds.includes(modelId)) delete customer.defaults[kind];
  }
}
async function saveCustomer() {
  if (!customerDraft.value) return;
  const previous = state.value.customers.find(item => item.id === customerDraft.value?.id);
  if (previous?.modelIds.some(id => !customerDraft.value?.modelIds.includes(id))) {
    if (!await ElMessageBox.confirm("撤销模型授权后，该客户全部账号不能再用该模型提交新任务；历史作品保留。", "确认授权调整", { confirmButtonText: "保存调整", cancelButtonText: "返回编辑" }).then(() => true, () => false)) return;
  }
  await perform({ type: "customer", value: clone(customerDraft.value) }, () => { customerVisible.value = false; });
