  }
  await perform({ type: "connection", value: clone(connectionDraft.value), credential: credential.value }, () => { connectionVisible.value = false; credential.value = ""; });
}
function addParameter() { modelDraft.value?.parameters.push({ key: `parameter${(modelDraft.value?.parameters.length ?? 0) + 1}`, name: "", options: [], value: "", exposed: false, required: false }); }
async function saveModel() {
  if (!modelDraft.value) return;
  if (modelDraft.value.parameters.some(item => !item.key.trim() || !item.name.trim() || !item.options.length) || new Set(modelDraft.value.parameters.map(item => item.key)).size !== modelDraft.value.parameters.length) { dialogError.value = "参数标识须唯一，并填写显示名称及可选值（用、分隔）"; return; }
  if (!modelDraft.value.id.trim() || !modelDraft.value.connectionId) { dialogError.value = "请填写模型标识并选择连接"; return; }
  if (!modelDraft.value.enabled && state.value.models.some(item => item.id === modelDraft.value?.id && item.enabled)) {
    const affected = state.value.customers.filter(item => item.modelIds.includes(modelDraft.value!.id));
    if (!await ElMessageBox.confirm(`下架将阻止${affected.length}个客户使用该模型提交新任务；历史作品保留。`, "确认下架", { confirmButtonText: "下架并保存", cancelButtonText: "返回编辑" }).then(() => true, () => false)) return;
  }
  await perform({ type: "model", value: clone(modelDraft.value) }, () => { modelVisible.value = false; });
}
async function saveNotice() { if (!noticeDraft.value?.customerIds.length) { dialogError.value = "请选择实际受影响的客户"; return; } if (noticeDraft.value && noticeConfirmed.value) await perform({ type: "notice", value: clone(noticeDraft.value) }, () => { noticeVisible.value = false; }); }
function pickTemplateFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (templateDraft.value?.kind === "video" && file.type !== "video/mp4" || templateDraft.value?.kind === "project" && !file.name.toLowerCase().endsWith(".json")) { dialogError.value = "请选择有效的MP4视频或JSON项目快照"; return; } if (file.size > 100 * 1024 * 1024) { dialogError.value = "模板文件不能超过100MB"; return; } templateFile.value = file; dialogError.value = ""; }
async function saveTemplate() { if (templateDraft.value) await perform({ type: "template", value: clone(templateDraft.value), source: templateFile.value }, () => { templateVisible.value = false; }); }
onMounted(loadPlatform);
</script>
